assert.equal(published.status, 201, await published.text());

// Volter Editor's Poly Haven helpers (volter-ai/editor b86dde8c5618, packages/editor-core/server/asset-library-routes.ts),
// their types removed; its cache is the module's own map
const cache = new Map();
const getCached = (key) => cache.get(key);
const setCache = (key, value) => cache.set(key, value);
const PH_HEADERS = { 'User-Agent': 'Volter-Editor/1.0' };
function phTypeToUnified(phType) {
  if (phType === 'hdris') return 'hdri';
  if (phType === 'textures') return 'texture';
  return 'model';
}
async function searchPolyHaven(type, category) {
  const cacheKey = `ph:${type}:${category ?? ''}`;
  const cached = getCached(cacheKey);
  if (cached) return cached;
  let url = `https://api.polyhaven.com/assets?type=${type}`;
  if (category) url += `&categories=${category}`;
  const res = await fetch(url, { headers: PH_HEADERS });
  if (!res.ok) throw new Error(`Poly Haven API error: ${res.status}`);
  const data = await res.json();
  const assets = Object.entries(data).map(([id, entry]) => ({
    id,
    source: 'polyhaven',
    name: entry.name,
    type: phTypeToUnified(type),
    thumbnailUrl: `https://cdn.polyhaven.com/asset_img/thumbs/${id}.png?width=256`,
    categories: entry.categories ?? [],
    tags: entry.tags ?? [],
    ...(entry.download_count != null ? { downloadCount: entry.download_count } : {}),
  }));
  const result = { assets, total: assets.length };
  setCache(cacheKey, result);
  return result;
}
async function getPolyHavenFiles(id) {
  const cacheKey = `ph-files:${id}`;
  const cached = getCached(cacheKey);
  if (cached) return cached;
  const res = await fetch(`https://api.polyhaven.com/files/${id}`, { headers: PH_HEADERS });
  if (!res.ok) throw new Error(`Poly Haven files API error: ${res.status}`);
  const data = await res.json();
  const files = [];
  // Models: GLTF with included files (bin + textures)
  if (data['gltf']) {
    for (const [resolution, formats] of Object.entries(data['gltf'])) {
      const gltfInfo = formats['gltf'];
      if (!gltfInfo) continue;
      const includes = [];
      let totalSize = gltfInfo.size;
      if (gltfInfo.include) {
        for (const [relPath, fileInfo] of Object.entries(gltfInfo.include)) {
          includes.push({ relativePath: relPath, url: fileInfo.url, size: fileInfo.size });
          totalSize += fileInfo.size;
        }
      }
      const entry = { label: `GLTF ${resolution}`, format: 'gltf', url: gltfInfo.url, sizeBytes: totalSize };
      if (includes.length > 0) entry.includes = includes;
      files.push(entry);
    }
  }
  // HDRIs
  if (data['hdri']) {
    for (const [resolution, formats] of Object.entries(data['hdri'])) {
      for (const [fmt, info] of Object.entries(formats)) {
        files.push({ label: `${fmt.toUpperCase()} ${resolution}`, format: fmt, url: info.url, sizeBytes: info.size });
      }
    }
  }
  setCache(cacheKey, files);
  return files;
}
async function categories(type) {
  const response = await fetch(`https://api.polyhaven.com/categories/${type}`, { headers: PH_HEADERS });
  if (!response.ok) throw new Error(`${response.status}`);
  const data = await response.json();
  return Object.keys(data).sort();
}
/** Download a single file to a destination path (the import route's downloadFile, its progress reporter left out). */
async function downloadFile(fileUrl, destPath) {
  await mkdir(join(destPath, '..'), { recursive: true });
  const response = await fetch(fileUrl);
  if (!response.ok || !response.body) {
    throw new Error(`Download failed: ${response.status} for ${fileUrl}`);
  }
  await pipeline(Readable.fromWeb(response.body), createWriteStream(destPath));
}

// the artist opens the model browser on furniture, picks the armchair, and imports its 1k glTF
assert.ok((await categories('models')).includes('furniture'), 'the category picker offers furniture');
const found = await searchPolyHaven('models', 'furniture');
const chair = found.assets.find((asset) => asset.id === 'ArmChair_01');
assert.equal(chair?.name, 'Arm Chair 01');
assert.equal(chair.type, 'model');
assert.deepEqual(chair.categories, ['furniture', 'seating']);
const thumb = await fetch(chair.thumbnailUrl);
assert.equal(thumb.status, 200, 'the browser shows the thumbnail the server built');
assert.deepEqual([...new Uint8Array(await thumb.arrayBuffer()).slice(0, 4)], [0x89, 0x50, 0x4e, 0x47]);
const files = await getPolyHavenFiles('ArmChair_01');
const gltf = files.find((file) => file.label === 'GLTF 1k');
assert.ok(gltf, 'the asset offers its 1k glTF: ' + JSON.stringify(files));
assert.deepEqual(gltf.includes.map((i) => i.relativePath).sort(), ['ArmChair_01.bin', 'textures/Armchair_01_diff_1k.png']);
const dir = 'asset-library/polyhaven/ArmChair_01';
await downloadFile(gltf.url, join(dir, 'ArmChair_01.gltf'));
for (const include of gltf.includes) await downloadFile(include.url, join(dir, include.relativePath));
const scene = JSON.parse(await readFile(join(dir, 'ArmChair_01.gltf'), 'utf8'));
assert.equal(scene.buffers[0].uri, 'ArmChair_01.bin');
assert.equal((await readFile(join(dir, 'ArmChair_01.bin'))).length, scene.buffers[0].byteLength);
assert.deepEqual([...(await readFile(join(dir, 'textures/Armchair_01_diff_1k.png'))).subarray(0, 4)], [0x89, 0x50, 0x4e, 0x47]);
const sizes = (await Promise.all([join(dir, 'ArmChair_01.gltf'), ...gltf.includes.map((i) => join(dir, i.relativePath))].map((p) => readFile(p)))).reduce((n, b) => n + b.length, 0);
assert.equal(sizes, gltf.sizeBytes, 'the imported files are the sizes the file list announced');
console.log(JSON.stringify({ imported: dir, files: [ 'ArmChair_01.gltf', ...gltf.includes.map((i) => i.relativePath) ], bytes: sizes }));
